from pathlib import Path
from html import escape,unescape
import json,re
root=Path(__file__).resolve().parent.parent
capture=json.loads((root/'capture-validation.json').read_text())
r=capture['scenario_results']
assert r['roads']['road']=='Boulevard Henri Arlet'
# The first check preceded layout settlement; each saved capture has a later check.
widget_checks=capture['widget_checks']
assert len(widget_checks) in (6,7)
preparatory_check=len(widget_checks)==7
assert all(v == 1.0 for item in widget_checks[int(preparatory_check):] for v in item['widgets'].values())
assert not capture['python_errors']
assert [x for x in capture['checks'] if x[0]=='FAIL'] == ([['FAIL','vector: critical widgets fully visible']] if preparatory_check else [])
title='FilterMate 5: five practical ways to connect vectors, rasters and LiDAR in QGIS'
figures=[]
def visual(stem,caption,alt,controls_caption,controls_alt,terrain=False):
 figures.extend([(stem+'.jpg',caption,alt),(stem+'-settings.jpg',controls_caption,controls_alt)])
 maps=''
 if terrain:
  figures.extend([(stem+'-terrain.jpg','The original FilterMate DTM clip with a local grayscale contrast stretch.','QGIS-rendered DTM elevation inside the church buffer, with a yellow church outline and RGB context.'),(stem+'-map.jpg','Classified LiDAR clipped to the same church buffer.','QGIS-rendered LiDAR classification colours clipped to the church and its 50 metre buffer.')])
  maps=f'<div class="map-pair"><div><img src="screenshots/{stem}-terrain.jpg" alt="The DTM clipped around the church"><small>DTM elevation · local contrast</small></div><div><img src="screenshots/{stem}-map.jpg" alt="The LiDAR cloud clipped to the same boundary"><small>Classified LiDAR</small></div></div>'
 return f'''<figure class="context"><img src="screenshots/{stem}.jpg" alt="{escape(alt)}"><figcaption>{caption}</figcaption>{maps}</figure>
<figure class="controls"><img src="screenshots/{stem}-settings.jpg" alt="{escape(controls_alt)}"><figcaption><strong>Widget detail.</strong> {controls_caption}</figcaption></figure>'''
sections=[]
sections.append(('', '''<p>A street corridor, a survey site or a slope threshold can each become the starting point for a QGIS analysis. The next step is usually to carry that selection across several layers.</p>
<p><strong>FilterMate 5 brings vector, raster and LiDAR sources into the same filtering panel.</strong> Select features, pixels or points, define their spatial relationship to the target layers, and work with the result in the existing project.</p>
<p>These five examples use a checked dataset from <strong>Sarlat-la-Canéda, France</strong>. Each includes a full QGIS view with its Layers panel and toolbars, followed by a larger view of the widgets that control the operation.</p>'''))
sections.append(('1. Prepare a focused street corridor', f'''<p>For a small works or survey dossier, start with a named street rather than the whole road hierarchy.</p>
<p>Select the <strong>{r['roads']['selected_road_segments']} segments of Boulevard Henri Arlet</strong>, choose Buildings and Parcels as targets, set <strong>Intersect</strong> and a <strong>50 m buffer</strong>. The result retains <strong>{r['roads']['buildings']} buildings and {r['roads']['parcels']} parcels</strong> from the complete tile datasets.</p>
<p class="recipe"><strong>Read the widgets:</strong> the street-name expression identifies the source; the target list scopes the output; the buffer defines the corridor. Orange buildings and teal parcel outlines show the result over the RGB orthophoto.</p>'''+visual('01_roads_buildings','A named-street corridor keeps the result small enough to inspect. The full QGIS interface remains visible.','Full QGIS view with Layers, Browser and toolbars, showing buildings and parcels within 50 metres of Boulevard Henri Arlet.','Street expression, Buildings and Parcels targets, Intersect predicate and 50 m buffer.','Native FilterMate widget crops showing the named-street expression, Buildings and Parcels targets, Intersect and a 50 metre buffer.')))
sections.append(('2. Give the DTM and LiDAR the same survey boundary', '''<p>Select the church building and apply a <strong>50 m buffer</strong> to two targets: the <strong>1 m digital terrain model</strong> and the <strong>LiDAR HD cloud</strong>.</p>
<p>The building is outlined in yellow. Separate map views show the clipped terrain and point cloud so one does not hide the other. Both results remain in the project layers with their styles and can be exported for the same working area.</p>
<p class="recipe"><strong>Read the widgets:</strong> Single Selection identifies the church; the target list contains both the DTM and LiDAR; the predicate and buffer define their shared boundary.</p>'''+visual('02_church_dtm_lidar','The yellow outline identifies the selected building. Both outputs use the same 50 m boundary.','Full QGIS window showing the selected church and clipped LiDAR, with the Layers list and FilterMate targets visible.','Single Selection, the two target layers and the 50 m buffer.','Native FilterMate widgets showing Church in Single Selection, DTM and LiDAR targets, Intersect and a 50 metre buffer.',terrain=True)))
sections.append(('3. Find parcels dominated by steep ground', f'''<p>Use the DTM as the source and choose <strong>Slope (%)</strong>. Set the minimum to <strong>20%</strong>, then require <strong>at least 50% coverage</strong> of each target parcel.</p>
<p><strong>{r['slope']['parcels']} parcels</strong> meet that rule on the tile. Amber pixels show the selected slope areas; teal outlines identify the retained parcels. The RGB orthophoto supplies context beneath the selection.</p>
<p class="recipe"><strong>Read the widgets:</strong> Quantity is Slope (%); the histogram and Min field define the pixel selection; coverage ≥ 50% controls how much of a parcel must overlap. A small intersection alone does not retain a parcel.</p>'''+visual('03_slope_parcels','Amber: selected slope pixels. Teal outlines: parcels passing the 50% coverage criterion. Tile-wide count; the map shows a detail.','QGIS showing selected steep-ground pixels in amber and retained parcels in teal over a natural-colour orthophoto, beside the complete histogram and threshold widgets.','Slope quantity, complete histogram, Min and Max fields, Parcels target and coverage ≥ 50%.','Large native widget detail showing Slope percent, the full histogram, a minimum of 20 percent, the Parcels target and 50 percent coverage.')))
sections.append(('4. Find parcels with a substantial vegetation signal', f'''<p>Use the colour-infrared orthophoto and assign its band roles: <strong>NIR, red and green</strong>. Insert the <strong>NDVI &gt; 0.3</strong> preset, then filter parcels with <strong>at least 50% coverage</strong>.</p>
<p><strong>{r['ndvi']['parcels']} parcels</strong> pass on this tile. Green pixels show the selected image areas over the natural-colour background; teal outlines show the retained parcels.</p>
<p class="recipe"><strong>Read the widgets:</strong> BANDS makes the NIR/red mapping explicit; RASTER EXPRESSION shows the complete formula; the target and coverage fields turn that pixel selection into a parcel query. The spectral threshold is an exploratory criterion, not a land-cover classification.</p>'''+visual('04_ndvi_parcels','Green: pixels matching NDVI > 0.3. Teal outlines: parcels passing the 50% coverage criterion. Tile-wide count; the map shows a detail.','Full QGIS view showing green selected vegetation pixels and retained parcels over an RGB orthophoto, with band roles and the full NDVI expression visible.','All three band roles, the complete two-band NDVI expression, Parcels target and coverage ≥ 50%.','Native FilterMate widget close-up with NIR, red and green band roles, the complete NDVI greater than 0.3 formula, Parcels target and 50 percent coverage.')))
sections.append(('5. Check vegetation proximity on the same boulevard', f'''<p>For a more focused LiDAR example, first make an explicit candidate layer containing the <strong>{r['high_vegetation']['candidate_road_segments']} Boulevard Henri Arlet road segments</strong>. The complete road dataset remains available in the project.</p>
<p>Select <strong>LiDAR class 5 — High vegetation</strong> and apply an <strong>Intersect</strong> query with a <strong>3 m buffer</strong> to that candidate layer. <strong>{r['high_vegetation']['road_segments']} of {r['high_vegetation']['candidate_road_segments']} segments</strong> meet the rule, giving a short list to inspect.</p>
<p class="recipe"><strong>Read the widgets:</strong> only class 5 is checked; the target name identifies the boulevard subset; the buffer is 3 m. The relationship is measured against the selected points’ footprint, not individual tree-to-road distances. This is a screening result, not a pruning diagnosis.</p>'''+visual('05_high_vegetation_roads','A scoped LiDAR query checks the same boulevard instead of highlighting most of the town.','Full QGIS window with Layers and toolbars showing high-vegetation LiDAR points and matching road segments on Boulevard Henri Arlet.','Class 5 selected, the explicit boulevard candidate layer, Intersect and a 3 m buffer.','Large native FilterMate widgets showing High vegetation class 5, the Boulevard Henri Arlet target, Intersect and a 3 metre buffer.')))
sections.append(('What changes in version 5', '''<p>Each data type can be a source or target, opening <strong>nine filtering directions</strong>. Raster exploration adds histogram ranges, pipettes, band roles and spectral presets. LiDAR exploration adds classes, attribute conditions and height above a DTM.</p>
<p>The workflow can be reused through favorites, <strong>nine Processing algorithms and four models</strong>, Python, the optional REST API and an MCP server. Remote-source support depends on the provider and operation, with bounded reads and cancellation support.</p>
<p>Export vector formats or a GeoPackage with an embedded project, GeoTIFF/COG rasters, and LAS/LAZ/COPC point clouds. Height above a DTM and COPC writing require PDAL 2.4 or later.</p>'''))
sections.append(('Try it on your own project', '''<p>FilterMate is <strong>free and open source under GPL v3</strong>, supporting QGIS 3.22 through 4.x. Point cloud layers require QGIS 3.26 or later.</p>
<p>Find the <a href="https://github.com/imagodata/filter_mate">code and releases</a>, <a href="https://github.com/imagodata/filter_mate/blob/main/CHANGELOG.md">release notes</a> and <a href="https://imagodata.github.io/filter_mate/guide.html">user guide</a>.</p>
<p><strong>Which source-to-target combination would make your next QGIS task easier?</strong></p>
<p class="credits">Captured in QGIS 4.2.3. BD TOPO®, orthophotos and LiDAR HD © IGN; cadastre © DGFiP/Etalab, September 2026. Open Licence 2.0. The DTM is a demonstration derivative of LiDAR ground points with interpolated gaps. Settings views stack native widget crops to remove unused space; full-window screenshots are supplied separately.</p>'''))
body='\n'.join('<section class="case">'+('<h2>'+escape(name)+'</h2>' if name else '')+text+'</section>' for name,text in sections)
style=(root/'article.css').read_text()
html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><style>{style}</style></head><body><main><header><div class="eyebrow">FilterMate 5 · QGIS · Five practical examples</div><h1>{escape(title)}</h1><nav><a href="linkedin-article.txt">Copy the article</a><a href="linkedin-article.pdf">PDF edition</a><a href="screenshot-captions.txt">Captions and alt text</a><a href="screenshots-overview.jpg">Screenshot overview</a></nav></header>{body}</main></body></html>'''
(root/'linkedin-article.html').write_text(html)
def plain(text):
 text=re.sub(r'<figure.*?</figure>','',text,flags=re.S)
 text=re.sub(r'<a href="([^"]+)">(.*?)</a>',lambda m:m[2]+' ('+m[1]+')',text)
 text=text.replace('</p>','\n\n')
 return unescape(re.sub(r'<[^>]+>','',text)).strip()
text=title+'\n\n'+'\n\n'.join((name+'\n\n' if name else '')+plain(text) for name,text in sections)+'\n'
text=re.sub(r'\n{3,}','\n\n',text)
(root/'linkedin-article.txt').write_text(text)
(root/'screenshot-captions.txt').write_text('\n\n'.join(f'{i}. {file}\nCaption: {caption}\nAlt text: {alt}' for i,(file,caption,alt) in enumerate(figures,1))+'\n')
post=f'''FilterMate 5 connects vector, raster and LiDAR selections inside QGIS.\n\nThe article walks through five focused tasks in Sarlat-la-Canéda:\n• A 50 m street corridor: {r['roads']['buildings']} buildings and {r['roads']['parcels']} parcels.\n• One survey boundary for a DTM and LiDAR cloud.\n• Parcels with at least 50% coverage by slopes ≥ 20%.\n• Parcels with at least 50% coverage by an NDVI > 0.3 selection.\n• High-vegetation proximity on a scoped boulevard network.\n\nEach example includes the normal QGIS window and a larger widget detail, so you can read the source criteria, targets, predicate, buffer and coverage settings.\n\nFree and open source: https://github.com/imagodata/filter_mate\n\nWhich combination would you try first?\n\n#QGIS #GIS #LiDAR #OpenSource #Geospatial\n'''
(root/'linkedin-post.txt').write_text(post)
print('Revised English article:',len(text.split()),'words; screenshot figures:',len(figures))
